// ==============================================================================
// CHU KỲ KÍCH HOẠT SOLENOID 4 NHỊP (GẠT CHÍNH & 3 NHỊP DỨT ĐIỂM CHỐNG KẸT)
// ------------------------------------------------------------------------------
// t = 0.0s: Cảm biến LJ12A3 phát hiện phôi kim loại khi băng chuyền đang chạy
// t = 2.0s: Bắt đầu duỗi lần 1 (giữ 2.0s gạt chính)
// t = 4.0s: Dừng duỗi lần 1 (nghỉ xả nhiệt 1.7s)
// t = 5.7s: Bắt đầu duỗi lần 2 (0.5s)
// t = 6.2s: Dừng duỗi lần 2 (nghỉ xả nhiệt 1.7s)
// t = 7.9s: Bắt đầu duỗi lần 3 (0.5s)
// t = 8.4s: Dừng duỗi lần 3 (nghỉ xả nhiệt 1.7s)
// t = 10.1s: Bắt đầu duỗi lần 4 (0.5s dứt điểm)
// t = 10.6s: Dừng duỗi lần 4 (hoàn tất chu kỳ phân loại 4 nhịp)
// ==============================================================================

let cycleTimers = context.get('cycleTimers') || [];

function clearAllCycleTimers() {
    cycleTimers.forEach(t => clearTimeout(t));
    cycleTimers = [];
    context.set('cycleTimers', []);
}

// 1. Xử lý lệnh HỦY CHU KỲ (khi dừng băng chuyền hoặc reset)
if (msg.topic === "cancel_cycle" || msg.payload === false) {
    clearAllCycleTimers();
    node.send([
        null,
        { payload: false, topic: "solenoid_off", adr: 1, text: "Dừng băng tải - Thu hồi Solenoid an toàn" }
    ]);
    return null;
}

// 2. CHỈ KÍCH HOẠT KHI ĐÚNG TOPIC "trigger" VÀ BĂNG CHUYỀN ĐANG CHẠY
let conveyorRunning = flow.get('conveyorRunning') || false;
if (msg.topic === "trigger" && conveyorRunning) {
    clearAllCycleTimers();

    // 1. Tại t = 2.0s: Bắt đầu duỗi lần 1 (giữ lâu 2.0s)
    let t1 = setTimeout(() => {
        if (!flow.get('conveyorRunning')) return;
        node.send([
            { payload: true, topic: "solenoid_on", adr: 1, text: "Kích hoạt Solenoid nhịp 1 (duỗi 2.0s)" },
            null
        ]);
    }, 2000);
    cycleTimers.push(t1);

    // 2. Tại t = 4.0s: Dừng duỗi lần 1, nghỉ 1.7s
    let t2 = setTimeout(() => {
        node.send([
            null,
            { payload: false, topic: "solenoid_off", adr: 1, text: "Thu hồi Solenoid nhịp 1 (nghỉ 1.7s)" }
        ]);
    }, 4000);
    cycleTimers.push(t2);

    // 3. Tại t = 5.7s: Bắt đầu duỗi lần 2 (0.5s)
    let t3 = setTimeout(() => {
        if (!flow.get('conveyorRunning')) return;
        node.send([
            { payload: true, topic: "solenoid_on", adr: 1, text: "Kích hoạt Solenoid nhịp 2 (duỗi 0.5s)" },
            null
        ]);
    }, 5700);
    cycleTimers.push(t3);

    // 4. Tại t = 6.2s: Dừng duỗi lần 2, nghỉ 1.7s
    let t4 = setTimeout(() => {
        node.send([
            null,
            { payload: false, topic: "solenoid_off", adr: 1, text: "Thu hồi Solenoid nhịp 2 (nghỉ 1.7s)" }
        ]);
    }, 6200);
    cycleTimers.push(t4);

    // 5. Tại t = 7.9s: Bắt đầu duỗi lần 3 (0.5s)
    let t5 = setTimeout(() => {
        if (!flow.get('conveyorRunning')) return;
        node.send([
            { payload: true, topic: "solenoid_on", adr: 1, text: "Kích hoạt Solenoid nhịp 3 (duỗi 0.5s)" },
            null
        ]);
    }, 7900);
    cycleTimers.push(t5);

    // 6. Tại t = 8.4s: Dừng duỗi lần 3, nghỉ 1.7s
    let t6 = setTimeout(() => {
        node.send([
            null,
            { payload: false, topic: "solenoid_off", adr: 1, text: "Thu hồi Solenoid nhịp 3 (nghỉ 1.7s)" }
        ]);
    }, 8400);
    cycleTimers.push(t6);

    // 7. Tại t = 10.1s: Bắt đầu duỗi lần 4 (0.5s dứt điểm)
    let t7 = setTimeout(() => {
        if (!flow.get('conveyorRunning')) return;
        node.send([
            { payload: true, topic: "solenoid_on", adr: 1, text: "Kích hoạt Solenoid nhịp 4 (duỗi 0.5s dứt điểm)" },
            null
        ]);
    }, 10100);
    cycleTimers.push(t7);

    // 8. Tại t = 10.6s: Dừng duỗi lần 4, hoàn tất chu kỳ
    let t8 = setTimeout(() => {
        node.send([
            null,
            { payload: false, topic: "solenoid_off", adr: 1, text: "Thu hồi Solenoid hoàn tất chu kỳ phân loại 4 nhịp" }
        ]);
        clearAllCycleTimers();
    }, 10600);
    cycleTimers.push(t8);

    context.set('cycleTimers', cycleTimers);
}

return null;

// ==============================================================================
// BỘ ĐẾM & BỘ LỌC SƯỜN LÊN ĐƠN CẢM BIẾN (LJ12A3 - KHÓA LIÊN ĐỘNG & CHỐNG NHIỄU)
// ==============================================================================

let metalCount = flow.get('metalCount') || 0;
let conveyorRunning = flow.get('conveyorRunning') || false;
let lastMetalState = context.get('lastMetalState') || false;
let isInitialized = context.get('isInitialized') || false;
let motorStartTime = context.get('motorStartTime') || 0;

// 1. Xử lý lệnh điều khiển Băng tải
if (msg.topic === "conveyor_cmd") {
    let run = Array.isArray(msg.payload) ? Boolean(msg.payload[0]) : Boolean(msg.payload);
    flow.set('conveyorRunning', run);
    if (run) {
        context.set('motorStartTime', Date.now());
    } else {
        context.set('lastMetalState', false);
        return [
            null,
            null,
            { payload: false, topic: "cancel_cycle", text: "Dừng băng tải - Hủy chu kỳ Solenoid" }
        ];
    }
    return null;
}

if (msg.topic === "simulate_disconnect" || msg.topic === "clear_log") {
    return null;
}

// 2. Xử lý các lệnh Reset chọn lọc
if (msg.topic === "reset" || msg.payload === "reset" || msg.topic === "reset_all" || msg.topic === "reset_counter" || msg.topic === "clear_all_data") {
    metalCount = 0;
    flow.set('metalCount', 0);
    flow.set('totalCount', 0);
    context.set('lastMetalState', false);
    return [
        { payload: 0, topic: "metal" },     // Out 1: SP Kim loại
        { payload: 0, topic: "total" },     // Out 2: Tổng sản phẩm
        { payload: false, topic: "cancel_cycle" } // Out 3: Hủy Solenoid
    ];
} else if (msg.topic === "reset_metal") {
    metalCount = 0;
    flow.set('metalCount', 0);
    flow.set('totalCount', 0);
    context.set('lastMetalState', false);
    return [
        { payload: 0, topic: "metal" },
        { payload: 0, topic: "total" },
        null
    ];
} else if (msg.topic === "reset_stats") {
    return null;
}

// 3. Xử lý tín hiệu cảm biến IN1 (LJ12A3 kim loại)
let isMetal = false;

if (msg.topic === "simulate_metal") {
    isMetal = true;
} else if (msg.topic === "" || msg.topic === "sensor" || msg.topic === "polling" || !msg.topic) {
    if (Array.isArray(msg.payload)) {
        isMetal = Boolean(msg.payload[0]); // Chỉ dùng IN1 (Cảm biến từ LJ12A3)
    } else if (typeof msg.payload === "boolean") {
        isMetal = msg.payload;
    }
}

// 4. CHỐNG BẪY SƯỜN LÊN KHI KHỞI ĐỘNG HỆ THỐNG / MỞ WEB
if (!isInitialized) {
    context.set('isInitialized', true);
    context.set('lastMetalState', isMetal);
    return null;
}

// 5. KHÓA LIÊN ĐỘNG: BĂNG TẢI PHẢI ĐANG CHẠY MỚI NHẬN DIỆN & PHÂN LOẠI
conveyorRunning = flow.get('conveyorRunning') || false;
if (!conveyorRunning) {
    context.set('lastMetalState', isMetal);
    return null;
}

// 6. VÙNG BLANKING CHỐNG NHIỄU DÒNG MỞ MÁY ĐỘNG CƠ (1000ms)
if (motorStartTime > 0 && (Date.now() - motorStartTime < 1000)) {
    context.set('lastMetalState', isMetal);
    return null;
}

// 7. SƯỜN LÊN KIM LOẠI: Cảm biến phát hiện phôi kim loại khi băng tải đang chạy
if (isMetal && !lastMetalState) {
    context.set('lastMetalState', true);
    metalCount += 1;
    flow.set('metalCount', metalCount);
    flow.set('totalCount', metalCount); // Đơn cảm biến: tổng = kim loại

    return [
        { payload: metalCount, topic: "metal" },   // Out 1: SP Kim loại
        { payload: metalCount, topic: "total" },   // Out 2: Tổng sản phẩm
        { payload: true, topic: "trigger" }        // Out 3: Kích hoạt Solenoid
    ];
}

if (!isMetal) context.set('lastMetalState', false);

return null;

// ==============================================================================
// QUẢN LÝ TRẠNG THÁI SCADA & NHẬT KÝ & GÓI TIN MODBUS RTU (POLL INSPECTOR)
// ==============================================================================

let state = flow.get('scada_state') || 'STOPPED';
let statusText = flow.get('scada_statusText') || 'Hệ thống đang dừng';
let conveyorRunning = flow.get('conveyorRunning') || false;
let metalCount = flow.get('metalCount') || 0;
let totalCount = flow.get('totalCount') || 0;
let opEvents = flow.get('opEvents') || [];
let secEvents = flow.get('secEvents') || [];
let intervals = flow.get('intervals') || [];
let lastMetalTime = flow.get('lastMetalTime') || null;
let modbusPackets = flow.get('modbus_packets') || [];

// TRẠNG THÁI MODBUS RTU TẢ THỰC: Mặc định false (Offline) cho tới khi có tín hiệu thực tế
let modbusOnline = flow.get('modbusOnline');
if (modbusOnline === undefined) {
    modbusOnline = false;
    flow.set('modbusOnline', false);
}

let now = new Date();
let timeStr = now.toTimeString().split(' ')[0];
let timeMsStr = timeStr + '.' + ('00' + now.getMilliseconds()).slice(-3);
let soundTrigger = null;

function addOpEvent(tag, tagType, text) {
    opEvents.unshift({ time: timeStr, tag: tag, tagType: tagType, text: text });
    if (opEvents.length > 50) opEvents.pop();
    flow.set('opEvents', opEvents);
}

function addSecEvent(tag, tagType, text) {
    secEvents.unshift({ time: timeStr, tag: tag, tagType: tagType, text: text });
    if (secEvents.length > 50) secEvents.pop();
    flow.set('secEvents', secEvents);
}

function addModbusPacket(dir, fc, hex, desc, crc) {
    modbusPackets.unshift({
        time: timeMsStr,
        dir: dir,
        fc: fc,
        hex: hex,
        desc: desc,
        crc: crc || 'OK'
    });
    if (modbusPackets.length > 80) modbusPackets.pop();
    flow.set('modbus_packets', modbusPackets);
}

// Khởi tạo các gói tin Modbus mẫu nếu mảng đang rỗng
if (modbusPackets.length === 0) {
    addModbusPacket('RX', 'FC02', 'FF 02 01 00 90 60', 'Phản hồi IN1-8 = 0 [Trạng thái cảm biến sẵn sàng]');
    addModbusPacket('TX', 'FC02', 'FF 02 00 00 00 08 6C 12', 'Khởi tạo truyền thông Modbus RTU (Quét 8 ngõ vào số)');
    addModbusPacket('TX', 'FC05', 'FF 05 00 00 00 00 D8 14', 'Ghi Coil 0 = 0 [Khóa an toàn động cơ băng tải]');
    addModbusPacket('TX', 'FC05', 'FF 05 00 01 00 00 89 D4', 'Ghi Coil 1 = 0 [Thu hồi an toàn Solenoid]');
}

// =========================================================
// MẢNG 1: TRẠNG THÁI KẾT NỐI MODBUS & WATCHDOG HEARTBEAT
// =========================================================
if (msg.topic === 'heartbeat_status') {
    modbusOnline = Boolean(msg.payload);
    flow.set('modbusOnline', modbusOnline);
    if (modbusOnline) {
        addSecEvent('KẾT NỐI', 'success', 'Truyền thông Modbus ESP8266 ổn định (150ms)');
        addModbusPacket('TX', 'FC02', 'FF 02 00 00 00 08 6C 12', 'Truy vấn thăm dò Heartbeat Modbus [COM4 Polling 150ms]');
        addModbusPacket('RX', 'FC02', 'FF 02 01 00 90 60', 'Phản hồi Heartbeat Slave 255 [Bình thường]');
    } else {
        addSecEvent('TIMEOUT', 'danger', 'Mất kết nối Modbus RTU ESP8266 (COM4 Timeout)');
        addOpEvent('CẢNH BÁO', 'danger', 'Mất tín hiệu Modbus RTU COM4 - Kiểm tra cáp nối vật lý');
    }
} else if (msg.topic === 'simulate_disconnect') {
    modbusOnline = !Boolean(msg.payload);
    flow.set('modbusOnline', modbusOnline);
    if (!modbusOnline) {
        addSecEvent('TIMEOUT', 'danger', 'Giả lập rút cáp: Mất kết nối Modbus RTU COM4');
        addOpEvent('CẢNH BÁO', 'danger', 'Đã ngắt tín hiệu Modbus RTU COM4 (Simulate Disconnect)');
    } else {
        addSecEvent('KẾT NỐI', 'success', 'Giả lập cắm cáp: Đã khôi phục kết nối Modbus RTU COM4');
        addOpEvent('KẾT NỐI', 'success', 'Đã khôi phục tín hiệu Modbus RTU COM4 (Simulate Connect)');
    }
} else if (msg.topic === 'user_login') {
    soundTrigger = 'chime';
    addSecEvent('ĐĂNG NHẬP', 'primary', 'Kỹ sư ' + msg.payload + ' đăng nhập vào hệ thống');
} else if (msg.topic === 'user_logout') {
    soundTrigger = 'beep';
    addSecEvent('ĐĂNG XUẤT', 'info', 'Kỹ sư ' + msg.payload + ' đã đăng xuất khỏi hệ thống');
}

// =========================================================
// MẢNG 2: VẬN HÀNH, THIẾT BỊ & BẮT GÓI MODBUS RTU
// =========================================================
else if (msg.topic === 'conveyor_cmd') {
    let run = Array.isArray(msg.payload) ? Boolean(msg.payload[0]) : Boolean(msg.payload);
    if (run) {
        conveyorRunning = true;
        state = 'RUNNING';
        statusText = 'Băng chuyền đang hoạt động';
        soundTrigger = 'beep';
        addOpEvent('BĂNG TẢI', 'success', 'Khởi động động cơ băng chuyền vận hành');
        addModbusPacket('TX', 'FC05', 'FF 05 00 00 FF 00 99 E4', 'Ghi Coil 0 = 1 [Chạy động cơ băng tải]');
        addModbusPacket('RX', 'FC05', 'FF 05 00 00 FF 00 99 E4', 'Phản hồi xác nhận Coil 0 = 1 (Động cơ ON)');
    } else {
        conveyorRunning = false;
        flow.set('solenoidActive', false);
        state = 'STOPPED';
        statusText = 'Băng chuyền đã dừng';
        soundTrigger = 'beep';
        addOpEvent('BĂNG TẢI', 'danger', 'Dừng động cơ băng chuyền an toàn');
        addModbusPacket('TX', 'FC05', 'FF 05 00 00 00 00 D8 14', 'Ghi Coil 0 = 0 [Dừng động cơ băng tải]');
        addModbusPacket('RX', 'FC05', 'FF 05 00 00 00 00 D8 14', 'Phản hồi xác nhận Coil 0 = 0 (Động cơ OFF)');
    }
} else if (msg.topic === 'metal') {
    metalCount = msg.payload;
    totalCount = metalCount;
    state = 'SORTING';
    statusText = 'Phát hiện phôi kim loại #' + metalCount;
    soundTrigger = 'chime';
    addOpEvent('KIM LOẠI', 'warning', 'Cảm biến IN1 (LJ12A3) phát hiện phôi Fe #' + metalCount);
    addModbusPacket('RX', 'FC02', 'FF 02 01 01 51 A0', 'Phản hồi IN1 = 1 [Cảm biến tiệm cận bắt phôi Fe #' + metalCount + ']');

    let curTime = Date.now();
    if (lastMetalTime) {
        let diffSec = Math.round(((curTime - lastMetalTime) / 1000) * 10) / 10;
        if (diffSec > 0.5 && diffSec < 60) {
            intervals.push(diffSec);
            if (intervals.length > 25) intervals.shift();
            flow.set('intervals', intervals);
        }
    }
    lastMetalTime = curTime;
    flow.set('lastMetalTime', lastMetalTime);
} else if (msg.topic === 'solenoid_on' || ((msg.payload === true || (Array.isArray(msg.payload) && msg.payload[0] === true)) && msg.adr === 1)) {
    state = 'SORTING';
    flow.set('solenoidActive', true);
    statusText = msg.text || 'Solenoid kích hoạt đòn bẩy gạt phôi';
    soundTrigger = 'chime';
    addOpEvent('SOLENOID', 'warning', msg.text || 'Kích hoạt đòn bẩy Solenoid gạt phôi kim loại');
    addModbusPacket('TX', 'FC05', 'FF 05 00 01 FF 00 C8 24', 'Ghi Coil 1 = 1 [' + (msg.text || 'Bật Solenoid') + ']');
    addModbusPacket('RX', 'FC05', 'FF 05 00 01 FF 00 C8 24', 'Phản hồi xác nhận Coil 1 = 1');
} else if (msg.topic === 'solenoid_off' || msg.payload === false) {
    flow.set('solenoidActive', false);
    state = conveyorRunning ? 'RUNNING' : 'STOPPED';
    statusText = conveyorRunning ? 'Băng chuyền đang hoạt động' : 'Băng chuyền đã dừng';
    addOpEvent('SOLENOID', 'info', msg.text || 'Thu hồi đòn bẩy Solenoid về vị trí chờ');
    addModbusPacket('TX', 'FC05', 'FF 05 00 01 00 00 89 D4', 'Ghi Coil 1 = 0 [' + (msg.text || 'Thu hồi Solenoid') + ']');
    addModbusPacket('RX', 'FC05', 'FF 05 00 01 00 00 89 D4', 'Phản hồi xác nhận Coil 1 = 0');
}

// =========================================================
// MẢNG 3: CÁC LỆNH RESET CHỌN LỌC
// =========================================================
else if (msg.topic === 'reset_metal' || msg.topic === 'reset_counter') {
    metalCount = 0;
    totalCount = 0;
    flow.set('metalCount', 0);
    flow.set('totalCount', 0);
    soundTrigger = 'beep';
    addOpEvent('RESET', 'warning', 'Đã đặt lại bộ đếm phôi kim loại về 0');
} else if (msg.topic === 'reset_stats') {
    intervals = [];
    lastMetalTime = null;
    flow.set('intervals', []);
    flow.set('lastMetalTime', null);
    soundTrigger = 'beep';
    addOpEvent('RESET', 'info', 'Đã xóa dữ liệu chu kỳ & làm mới biểu đồ thống kê');
} else if (msg.topic === 'clear_modbus_log') {
    modbusPackets = [];
    flow.set('modbus_packets', []);
    addOpEvent('DỌN DẸP', 'info', 'Đã xóa nhật ký gói tin Modbus RTU');
} else if (msg.topic === 'reset' || msg.topic === 'reset_all' || msg.topic === 'clear_all_data') {
    metalCount = 0;
    totalCount = 0;
    intervals = [];
    lastMetalTime = null;
    modbusPackets = [];
    flow.set('metalCount', 0);
    flow.set('totalCount', 0);
    flow.set('intervals', []);
    flow.set('lastMetalTime', null);
    flow.set('modbus_packets', []);
    flow.set('solenoidActive', false);
    soundTrigger = 'beep';
    addOpEvent('RESET', 'danger', 'Đặt lại toàn bộ số liệu, biểu đồ và gói tin hệ thống');
}

flow.set('scada_state', state);
flow.set('scada_statusText', statusText);
flow.set('conveyorRunning', conveyorRunning);

msg.payload = {
    state: state,
    statusText: statusText,
    conveyorRunning: conveyorRunning,
    solenoidActive: flow.get('solenoidActive') || false,
    metalCount: flow.get('metalCount') || 0,
    totalCount: flow.get('metalCount') || 0,
    modbusOnline: modbusOnline,
    opEvents: opEvents,
    secEvents: secEvents,
    intervals: intervals,
    modbusPackets: modbusPackets,
    soundTrigger: soundTrigger,
    time: timeStr
};

return msg;

// Gate kiểm tra tín hiệu Modbus RTU ESP8266 thực tế
let isBlocked = flow.get('heartbeat_blocked') || false;

// Nếu là lệnh giả lập rút / cắm cáp từ giao diện
if (msg.topic === 'simulate_disconnect') {
    isBlocked = Boolean(msg.payload);
    flow.set('heartbeat_blocked', isBlocked);
    let isOnline = !isBlocked;
    flow.set('modbusOnline', isOnline);
    return { payload: isOnline, topic: 'heartbeat_status' };
}

// Nếu là dữ liệu đọc được từ Modbus Read thực tế (Output 1)
if (msg.topic !== 'heartbeat_check') {
    flow.set('lastModbusReadTime', Date.now());
    flow.set('modbusOnline', true);
    return null; // Không cần spam ui_template mỗi 150ms
}

// Nếu là nhịp kiểm tra định kỳ 1s từ inject
if (msg.topic === 'heartbeat_check') {
    let lastTime = flow.get('lastModbusReadTime') || 0;
    let now = Date.now();
    // Coi là Online nếu nhận được gói tin Modbus trong vòng 2.5 giây vừa qua
    let isOnline = (!isBlocked && (now - lastTime < 2500));
    flow.set('modbusOnline', isOnline);
    return { payload: isOnline, topic: 'heartbeat_status' };
}

return null;

// ==============================================================================
// BỘ ĐIỀU PHỐI LỆNH SCADA UI (ROUTER SCADA CMD)
// ==============================================================================
// - Out 1: Lệnh Động cơ (Coil 0) -> a01eb95a6d295e54, c8314e6b21da4320, a1b2c3d4e5f60003
// - Out 2: Lệnh BẬT Solenoid (Coil 1 = 1) -> 440cbdde9bf30775, a1b2c3d4e5f60003
// - Out 3: Lệnh TẮT Solenoid (Coil 1 = 0) -> 52be7f48da40b346, a1b2c3d4e5f60003
// - Out 4: Lệnh Reset / Simulate Sensor -> c8314e6b21da4320, a1b2c3d4e5f60003
// ==============================================================================

if (msg.topic === "conveyor_cmd") {
    let run = Boolean(Array.isArray(msg.payload) ? msg.payload[0] : msg.payload);
    let outMsg = { payload: run, topic: "conveyor_cmd" };
    return [outMsg, null, null, null];
}

if (msg.topic === "solenoid_manual" || msg.topic === "solenoid_cmd") {
    let active = Boolean(Array.isArray(msg.payload) ? msg.payload[0] : msg.payload);
    if (active) {
        return [
            null,
            { payload: true, topic: "solenoid_on", adr: 1, text: "Kích Solenoid 12V (Nhấn giữ thủ công)" },
            null,
            null
        ];
    } else {
        return [
            null,
            null,
            { payload: false, topic: "solenoid_off", adr: 1, text: "Nhả Solenoid 12V (Thu hồi vị trí chờ)" },
            null
        ];
    }
}

// Các lệnh Reset, Heartbeat, Giả lập cảm biến
if (msg.topic === "simulate_metal" || (msg.topic && msg.topic.startsWith("reset")) || (msg.topic && msg.topic.startsWith("clear_"))) {
    return [null, null, null, msg];
}

return null;
